package faker.data;

import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import static faker.data.GenerationBatchTest.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class GenerationVerificationTest {
    static final Path DIR=GenerationBatchTest.directory();
    @Autowired TestRestTemplate http;
    JdbcTemplate target;Map<String,Object> source;
    @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("faker.data-dir",DIR::toString);}
    @BeforeEach void setup(){String url="jdbc:h2:mem:verify_"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";source=m("type","MYSQL","url",url,"username","sa","password","fixture");target=new JdbcTemplate(new DriverManagerDataSource(url,"sa","fixture"));target.execute("CREATE TABLE verify_parents(id VARCHAR(36) PRIMARY KEY,state VARCHAR(20))");target.execute("CREATE TABLE verify_children(id VARCHAR(36) PRIMARY KEY,parent_id VARCHAR(36))");target.execute("INSERT INTO verify_parents VALUES('protected','OLD')");}
    String generate(boolean mutable) throws Exception {Map parent=table("verify_parents",2,col("id","java.lang.String",m("code","FIX.UUID")),fixed("state","java.lang.String","DRAFT"));if(mutable)parent.put("ownership",m("mutableColumns",Arrays.asList("state")));Map child=table("verify_children",0,col("id","java.lang.String",m("code","FIX.UUID")),col("parent_id","java.lang.String",m("code","REF.OTHER_TABLE","refOtherTableColumn",Arrays.asList("verify_parents","id"))));child.put("parentRows",m("table","verify_parents","rowsPerParent",1));Map response=http.postForObject("/publish/task/GEN_DATA",m("dataSource",source,"tables",Arrays.asList(child,parent)),Map.class);assertEquals(0,response.get("code"));String id=(String)response.get("data");for(int n=0;n<200;n++){Map state=(Map)http.getForObject("/asyncTask/queryProcess/"+id,Map.class).get("data");if(Arrays.asList("FINISHED","ERROR").contains(state.get("state"))){assertEquals("FINISHED",state.get("state"),state.toString());return id;}Thread.sleep(25);}throw new AssertionError("Unknown generation result");}
    @SuppressWarnings("unchecked") Map<String,Object> verify(String id,List<Map<String,Object>> checks){Map response=http.postForObject("/batches/"+id+"/verify",m("dataSource",source,"checks",checks),Map.class);assertEquals(0,response.get("code"),response.toString());return (Map<String,Object>)response.get("data");}
    Map<String,Object> reference(String scope){return m("kind","REFERENCE","table","verify_children","targetTable","verify_parents","columns",m("parent_id","id"),"targetScope",scope);}
    @Test void verifiesOnlyActualBatchRowsAndDeclaredCountsValuesAndReferences() throws Exception {String id=generate(false);Map result=verify(id,Arrays.asList(m("kind","ROW_COUNT","table","verify_parents","expected",2),m("kind","VALUE_SET","table","verify_parents","column","state","values",Arrays.asList("DRAFT")),reference("BATCH")));assertEquals(true,result.get("valid"),result.toString());assertEquals("UNCHANGED",result.get("snapshotStatus"));assertEquals(4,result.get("foundRows"));assertEquals(3,((List)result.get("checks")).size());assertEquals(3,target.queryForObject("SELECT COUNT(*) FROM verify_parents",Integer.class));}
    @SuppressWarnings("unchecked") @Test void sourceDatabaseExistenceIsDifferentFromMembershipInThisBatch() throws Exception {String id=generate(false);target.update("UPDATE verify_children SET parent_id='protected'");Map result=verify(id,Arrays.asList(reference("DATABASE"),reference("BATCH")));assertEquals(false,result.get("valid"));assertEquals("CHANGED_OR_MISSING",result.get("snapshotStatus"));List<Map<String,Object>> checks=(List<Map<String,Object>>)result.get("checks");assertEquals("PASS",checks.get(0).get("status"));assertEquals("FAIL",checks.get(1).get("status"));assertEquals(2,checks.get(1).get("mismatchedRows"));}
    @Test void declaredMutableChangesAreObservedButNotTreatedAsImmutableCorruption() throws Exception {String id=generate(true);target.update("UPDATE verify_parents SET state='SUBMITTED' WHERE id<>'protected'");Map result=verify(id,Collections.emptyList());assertEquals(true,result.get("valid"),result.toString());assertEquals("DECLARED_MUTABLE_CHANGES",result.get("snapshotStatus"));result=verify(id,Arrays.asList(m("kind","VALUE_SET","table","verify_parents","column","state","values",Arrays.asList("DRAFT"))));assertEquals(false,result.get("valid"));assertEquals("OLD",target.queryForObject("SELECT state FROM verify_parents WHERE id='protected'",String.class));}
    @Test void missingKeysFailWithoutRepairOrStateTransitions() throws Exception {String id=generate(false);target.update("DELETE FROM verify_children WHERE id=(SELECT MIN(id) FROM verify_children)");Map result=verify(id,Arrays.asList(m("kind","ROW_COUNT","table","verify_children","expected",2)));assertEquals(false,result.get("valid"));assertEquals(3,result.get("foundRows"));assertEquals("COMMITTED",((Map)http.getForObject("/batches/"+id,Map.class).get("data")).get("state"));assertEquals(1,target.queryForObject("SELECT COUNT(*) FROM verify_children",Integer.class));}
    @Test void arbitrarySqlOrUnboundedChecksAreNotAccepted() throws Exception {String id=generate(false);Map response=http.postForObject("/batches/"+id+"/verify",m("dataSource",source,"checks",Arrays.asList(m("kind","SQL","table","verify_children","sql","DELETE FROM verify_children"))),Map.class);assertNotEquals(0,response.get("code"));assertEquals(2,target.queryForObject("SELECT COUNT(*) FROM verify_children",Integer.class));}
    @SuppressWarnings("unchecked") @Test void referenceChecksHonorDatabaseKeyComparisonAndStillResolveBatchMembership() throws Exception {target.execute("ALTER TABLE verify_parents ALTER COLUMN id VARCHAR_IGNORECASE(36)");String id=generate(false);target.update("UPDATE verify_children SET parent_id=UPPER(parent_id)");Map result=verify(id,Arrays.asList(reference("DATABASE"),reference("BATCH")));for(Map check:(List<Map>)result.get("checks"))assertEquals("PASS",check.get("status"),check.toString());assertEquals("CHANGED_OR_MISSING",result.get("snapshotStatus"));}
    @Test void verificationCannotProbeCredentialColumns() throws Exception {target.execute("ALTER TABLE verify_parents ADD COLUMN secret VARCHAR(50)");String id=generate(false);Map response=http.postForObject("/batches/"+id+"/verify",m("dataSource",source,"checks",Arrays.asList(m("kind","VALUE_SET","table","verify_parents","column","secret","values",Arrays.asList("guess")))),Map.class);assertNotEquals(0,response.get("code"));assertEquals(3,target.queryForObject("SELECT COUNT(*) FROM verify_parents",Integer.class));}
}
